import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';

const categories = ['Programming', 'Design', 'Business', 'Marketing', 'Photography', 'Music', 'Data Science', 'AI & ML'];

export default function InstructorPage() {
  const [courses, setCourses] = useState([]);
  const [view, setView] = useState('list'); // list | create | edit
  const [editCourse, setEditCourse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ title: '', description: '', shortDescription: '', category: 'Programming', level: 'beginner', price: 0, language: 'English', whatYouLearn: [''], requirements: [''], tags: '' });

  useEffect(() => {
    axios.get('/api/courses/instructor/my-courses')
      .then(r => setCourses(r.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const handleSave = async () => {
    try {
      const payload = { ...form, tags: form.tags.split(',').map(t => t.trim()).filter(Boolean), whatYouLearn: form.whatYouLearn.filter(Boolean), requirements: form.requirements.filter(Boolean) };
      if (editCourse) {
        const { data } = await axios.put(`/api/courses/${editCourse._id}`, payload);
        setCourses(cs => cs.map(c => c._id === data._id ? data : c));
        toast.success('✅ Course updated!');
      } else {
        const { data } = await axios.post('/api/courses', payload);
        setCourses(cs => [data, ...cs]);
        toast.success('🚀 Course created!');
      }
      setView('list'); setEditCourse(null);
    } catch (err) { toast.error(err.response?.data?.message || 'Save failed'); }
  };

  const startEdit = (c) => {
    setEditCourse(c);
    setForm({ ...c, tags: (c.tags || []).join(', '), whatYouLearn: c.whatYouLearn?.length ? c.whatYouLearn : [''], requirements: c.requirements?.length ? c.requirements : [''] });
    setView('create');
  };

  const togglePublish = async (c) => {
    try {
      const { data } = await axios.put(`/api/courses/${c._id}`, { isPublished: !c.isPublished });
      setCourses(cs => cs.map(x => x._id === data._id ? data : x));
      toast.success(data.isPublished ? '✅ Published!' : '⏸ Unpublished');
    } catch { toast.error('Failed'); }
  };

  const addListItem = (field) => setForm(f => ({ ...f, [field]: [...f[field], ''] }));
  const updateListItem = (field, i, val) => setForm(f => ({ ...f, [field]: f[field].map((x, j) => j === i ? val : x) }));
  const removeListItem = (field, i) => setForm(f => ({ ...f, [field]: f[field].filter((_, j) => j !== i) }));

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      <div className="page-container" style={{ padding: '40px 24px' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 36, flexWrap: 'wrap', gap: 16 }}>
          <div>
            <h1 style={{ fontSize: 32, fontWeight: 900 }}>
              Instructor <span style={{ background: 'linear-gradient(135deg, #7c3aed, #00f5d4)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Studio</span>
            </h1>
            <p style={{ color: '#6b6490', marginTop: 4 }}>Create and manage your courses</p>
          </div>
          {view === 'list' ? (
            <button className="btn btn-primary" onClick={() => { setEditCourse(null); setForm({ title: '', description: '', shortDescription: '', category: 'Programming', level: 'beginner', price: 0, language: 'English', whatYouLearn: [''], requirements: [''], tags: '' }); setView('create'); }}>
              + Create New Course
            </button>
          ) : (
            <button className="btn btn-ghost" onClick={() => setView('list')}>← Back to Courses</button>
          )}
        </div>

        {/* Stats */}
        {view === 'list' && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 16, marginBottom: 32 }}>
            {[
              { icon: '📚', label: 'Total Courses', value: courses.length },
              { icon: '✅', label: 'Published', value: courses.filter(c => c.isPublished).length },
              { icon: '👥', label: 'Total Students', value: courses.reduce((a, c) => a + (c.totalStudents || 0), 0) },
              { icon: '⭐', label: 'Avg Rating', value: courses.length ? (courses.reduce((a, c) => a + (c.averageRating || 0), 0) / courses.length).toFixed(1) : '—' },
            ].map(s => (
              <div key={s.label} className="glass" style={{ padding: '20px', textAlign: 'center', borderRadius: 14 }}>
                <div style={{ fontSize: 28, marginBottom: 6 }}>{s.icon}</div>
                <div style={{ fontSize: 26, fontWeight: 900, color: '#c084fc' }}>{s.value}</div>
                <div style={{ fontSize: 11, color: '#6b6490', marginTop: 2 }}>{s.label}</div>
              </div>
            ))}
          </div>
        )}

        {/* Course List */}
        {view === 'list' && (
          loading ? <div className="loader" style={{ margin: '60px auto' }} /> :
          courses.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '80px 0', border: '1px dashed rgba(124,58,237,0.3)', borderRadius: 20 }}>
              <div style={{ fontSize: 64, marginBottom: 16 }}>🎬</div>
              <h3 style={{ fontSize: 20, fontWeight: 700, marginBottom: 8 }}>No courses yet</h3>
              <p style={{ color: '#6b6490', marginBottom: 20 }}>Create your first course and start teaching!</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              {courses.map(c => (
                <div key={c._id} className="glass" style={{ padding: '20px 24px', borderRadius: 16, display: 'flex', alignItems: 'center', gap: 20, flexWrap: 'wrap' }}>
                  <div style={{ flex: 1, minWidth: 200 }}>
                    <div style={{ display: 'flex', gap: 8, marginBottom: 8, flexWrap: 'wrap' }}>
                      <span className="badge badge-purple">{c.category}</span>
                      <span className={`badge ${c.isPublished ? 'badge-neon' : 'badge-gold'}`}>{c.isPublished ? '✓ Live' : '⏸ Draft'}</span>
                      <span className="badge badge-pink">{c.level}</span>
                    </div>
                    <h3 style={{ fontSize: 17, fontWeight: 700, color: '#f0eeff', marginBottom: 4 }}>{c.title}</h3>
                    <div style={{ fontSize: 13, color: '#6b6490', display: 'flex', gap: 16, flexWrap: 'wrap' }}>
                      <span>👥 {c.totalStudents || 0} students</span>
                      <span>⭐ {c.averageRating || 0}</span>
                      <span>📚 {c.modules?.length || 0} modules</span>
                      <span>{c.price === 0 ? 'Free' : `$${c.price}`}</span>
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 10, flexShrink: 0 }}>
                    <button className="btn btn-ghost btn-sm" onClick={() => startEdit(c)}>✏️ Edit</button>
                    <button className={`btn btn-sm ${c.isPublished ? 'btn-ghost' : 'btn-neon'}`} onClick={() => togglePublish(c)}>
                      {c.isPublished ? '⏸ Unpublish' : '🚀 Publish'}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )
        )}

        {/* Create/Edit Form */}
        {view === 'create' && (
          <div style={{ maxWidth: 760 }}>
            <h2 style={{ fontSize: 24, fontWeight: 800, marginBottom: 28 }}>{editCourse ? '✏️ Edit Course' : '🚀 Create New Course'}</h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
              <div className="form-group">
                <label className="form-label">Course Title *</label>
                <input className="input" placeholder="e.g. Complete React Developer Bootcamp" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">Short Description</label>
                <input className="input" placeholder="One-line summary (shown in cards)" value={form.shortDescription} onChange={e => setForm(f => ({ ...f, shortDescription: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">Full Description *</label>
                <textarea className="input" rows={4} placeholder="Detailed course description..." value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} style={{ resize: 'vertical' }} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16 }}>
                <div className="form-group">
                  <label className="form-label">Category</label>
                  <select className="input" value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Level</label>
                  <select className="input" value={form.level} onChange={e => setForm(f => ({ ...f, level: e.target.value }))}>
                    {['beginner','intermediate','advanced'].map(l => <option key={l} value={l}>{l}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Price ($)</label>
                  <input className="input" type="number" min={0} value={form.price} onChange={e => setForm(f => ({ ...f, price: Number(e.target.value) }))} />
                </div>
              </div>
              <div className="form-group">
                <label className="form-label">Tags (comma-separated)</label>
                <input className="input" placeholder="react, javascript, frontend" value={form.tags} onChange={e => setForm(f => ({ ...f, tags: e.target.value }))} />
              </div>
              <div className="form-group">
                <label className="form-label">What Students Will Learn</label>
                {form.whatYouLearn.map((item, i) => (
                  <div key={i} style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
                    <input className="input" placeholder={`Learning outcome ${i + 1}`} value={item} onChange={e => updateListItem('whatYouLearn', i, e.target.value)} />
                    {form.whatYouLearn.length > 1 && <button onClick={() => removeListItem('whatYouLearn', i)} style={{ background: 'rgba(247,37,133,0.1)', border: '1px solid rgba(247,37,133,0.3)', borderRadius: 8, color: '#f72585', cursor: 'pointer', padding: '0 12px', fontWeight: 700 }}>×</button>}
                  </div>
                ))}
                <button className="btn btn-ghost btn-sm" onClick={() => addListItem('whatYouLearn')}>+ Add Outcome</button>
              </div>
              <div className="form-group">
                <label className="form-label">Requirements</label>
                {form.requirements.map((item, i) => (
                  <div key={i} style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
                    <input className="input" placeholder={`Requirement ${i + 1}`} value={item} onChange={e => updateListItem('requirements', i, e.target.value)} />
                    {form.requirements.length > 1 && <button onClick={() => removeListItem('requirements', i)} style={{ background: 'rgba(247,37,133,0.1)', border: '1px solid rgba(247,37,133,0.3)', borderRadius: 8, color: '#f72585', cursor: 'pointer', padding: '0 12px', fontWeight: 700 }}>×</button>}
                  </div>
                ))}
                <button className="btn btn-ghost btn-sm" onClick={() => addListItem('requirements')}>+ Add Requirement</button>
              </div>
              <div style={{ display: 'flex', gap: 12, paddingTop: 8 }}>
                <button className="btn btn-primary btn-lg" onClick={handleSave}>{editCourse ? '✓ Save Changes' : '🚀 Create Course'}</button>
                <button className="btn btn-ghost" onClick={() => setView('list')}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
